def check_latin(sq):
    n = len(sq)
    for i in range(n):
        if set(sq[i]) != set(range(n)):
            return False
        if set(sq[j][i] for j in range(n)) != set(range(n)):
            return False
    return True

def check_orthogonal(X, Y):
    n = len(X)
    pairs = set()
    for i in range(n):
        for j in range(n):
            p = (X[i][j], Y[i][j])
            if p in pairs:
                return False
            pairs.add(p)
    return True

n = 8

# Try X[i][j] = (i + j) mod 8, Y[i][j] = (i + 3j) mod 8
X = [[(i + j) % n for j in range(n)] for i in range(n)]
Y = [[(i + 3*j) % n for j in range(n)] for i in range(n)]

print("X is Latin:", check_latin(X))
print("Y is Latin:", check_latin(Y))
print("Orthogonal:", check_orthogonal(X, Y))
